import React from "react";
import { useNavigate } from "react-router-dom";

const Hero = () => {
  const navigate = useNavigate();

  return (
    <section className="hero">

      <div className="container">

        {/* LEFT */}
        <div className="left">

          <p className="tag">WELCOME</p>

          <h1>
            I'm <span className="name">Swetha A</span>
          </h1>

          <h2 className="role">
            Full Stack Developer • System Builder • UI Thinker
          </h2>

          <p className="desc">
            I design structured systems and build scalable applications
            where logic, performance, and user experience work together.
          </p>

          <div className="buttons">
            <button className="btn primary" onClick={() => navigate("/projects")}>
              Explore Projects →
            </button>
            <button className="btn secondary" onClick={() => navigate("/about")}>
              About Me →
            </button>
          </div>

        </div>

        {/* RIGHT */}
        <div className="right">

          <div className="system">

            {/* DARK PREMIUM RINGS */}
            <div className="ring ring1">
              <span className="dot d1"></span>
              <span className="dot d2"></span>
              <span className="dot d3"></span>
            </div>

            <div className="ring ring2">
              <span className="dot d4"></span>
              <span className="dot d5"></span>
            </div>

            {/* CENTER */}
            <div className="center">
              <img
                src="https://i.ibb.co/4f1R9Zc/female-avatar.png"
                alt="avatar"
              />
              <p>Swetha A</p>
            </div>

            {/* ORBIT LABELS (SPACED CLEANLY) */}
            <div className="orbit">

              <div className="node n1">Frontend Engineering</div>
              <div className="node n2">Backend Systems</div>
              <div className="node n3">API Architecture</div>
              <div className="node n4">Database Design</div>
              <div className="node n5">UI Experience</div>
              <div className="node n6">System Thinking</div>

            </div>

          </div>

        </div>

      </div>

      <style>{`

        .hero {
          min-height: 100vh;
          display: flex;
          align-items: center;
          background: radial-gradient(circle at top, #0b1220, #050816);
          padding: 0 8%;
        }

        .container {
          display: grid;
          grid-template-columns: 1.2fr 1fr;
          gap: 60px;
          width: 100%;
          align-items: center;
        }

        /* LEFT */
        .tag {
          font-size: 12px;
          letter-spacing: 3px;
          color: #64748b;
        }

        h1 {
          font-size: 62px;
        }

        .name {
          color: #38BDF8;
        }

        .role {
          font-size: 20px;
          color: #94a3b8;
        }

        .desc {
          margin-top: 18px;
          font-size: 16px;
          color: #cbd5e1;
          line-height: 1.7;
          max-width: 520px;
        }

        .buttons {
          margin-top: 30px;
          display: flex;
          gap: 15px;
        }

        .btn {
          padding: 12px 22px;
          border-radius: 10px;
          font-weight: 600;
          border: 1px solid rgba(56,189,248,0.3);
        }

        .primary {
          background: #38BDF8;
          color: #0b1220;
        }

        .secondary {
          background: rgba(255,255,255,0.03);
          color: #38BDF8;
        }

        /* SYSTEM */
        .system {
          position: relative;
          width: 360px;
          height: 360px;
          margin: auto;
        }

        /* 🌑 DARK PREMIUM RINGS */
        .ring {
          position: absolute;
          border-radius: 50%;
          border: 1px solid rgba(56,189,248,0.15);
          background: radial-gradient(
            circle,
            rgba(56,189,248,0.05),
            transparent 70%
          );
        }

        .ring1 {
          width: 340px;
          height: 340px;
          top: 10px;
          left: 10px;
        }

        .ring2 {
          width: 250px;
          height: 250px;
          top: 55px;
          left: 55px;
          border: 1px solid rgba(56,189,248,0.1);
        }

        /* ✨ STATIC GLOW PARTICLES ON RINGS */
        .dot {
          position: absolute;
          width: 6px;
          height: 6px;
          background: #38BDF8;
          border-radius: 50%;
          box-shadow: 0 0 10px rgba(56,189,248,0.8);
        }

        .d1 { top: 20px; left: 60px; }
        .d2 { bottom: 40px; right: 50px; }
        .d3 { top: 140px; right: 10px; }
        .d4 { top: 60px; left: 120px; }
        .d5 { bottom: 70px; left: 80px; }

        /* CENTER */
        .center {
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%,-50%);
          text-align: center;
        }

        .center img {
          width: 105px;
          height: 105px;
          border-radius: 50%;
          object-fit: cover;
          border: 2px solid rgba(56,189,248,0.5);
          box-shadow: 0 0 25px rgba(56,189,248,0.2);
        }

        .center p {
          font-size: 13px;
          color: #94a3b8;
          margin-top: 6px;
        }

        /* ORBIT LABELS — CLEAN SPACING */
        .orbit {
          position: absolute;
          width: 100%;
          height: 100%;
        }

        .node {
          position: absolute;
          padding: 8px 14px;
          border-radius: 20px;
          background: rgba(255,255,255,0.03);
          border: 1px solid rgba(56,189,248,0.18);
          font-size: 11px;
          color: #cbd5e1;
          white-space: nowrap;
          backdrop-filter: blur(6px);
        }

        /* spaced properly for visual balance */
        .n1 { top: 5%; left: 50%; transform: translateX(-50%); }
        .n2 { top: 50%; right: 5%; transform: translateY(-50%); }
        .n3 { bottom: 5%; left: 50%; transform: translateX(-50%); }
        .n4 { top: 50%; left: 5%; transform: translateY(-50%); }
        .n5 { top: 18%; right: 20%; }
        .n6 { bottom: 18%; left: 20%; }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .container {
            grid-template-columns: 1fr;
            text-align: center;
          }

          h1 {
            font-size: 42px;
          }

          .buttons {
            justify-content: center;
          }

          .system {
            margin-top: 40px;
          }
        }

      `}</style>

    </section>
  );
};

export default Hero;
